using System.Security.Claims;
using Fylkren.Api.ActivityAudit;
using Fylkren.Api.Persistence;
using Fylkren.Api.WorkManagement;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.EntityFrameworkCore;
using static Fylkren.Api.WorkManagement.WorkItemPolicy;

namespace Fylkren.Api.Risks;

public static class RiskEndpoints
{
 private static readonly HashSet<string> ObjectTypes=["task","assignment","plan","execution"];
 private static readonly HashSet<string> RiskStatuses=["identified","active","mitigating","accepted","closed"];
 private static readonly HashSet<string> ActionStatuses=["planned","in_progress","completed","cancelled"];
 public static IEndpointRouteBuilder MapRiskEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/risks").RequireAuthorization();g.MapGet("/sites/{siteId:guid}/{objectType}/{objectId:guid}",Get);g.MapPost("/sites/{siteId:guid}/{objectType}/{objectId:guid}",Create);g.MapPut("/{riskId:guid}",Revise);g.MapPost("/{riskId:guid}/mitigations",AddMitigation);g.MapPut("/mitigations/{mitigationId:guid}",ReviseMitigation);return e;}
 private static async Task<IResult> Get(Guid siteId,string objectType,Guid objectId,ClaimsPrincipal user,FylkrenDbContext db,CancellationToken ct){if(!PersonId(user,out var personId))return Results.Problem(statusCode:403);var item=await ContextItem(siteId,objectType,objectId,db,ct);if(item is null)return Results.NotFound();if(!await LeadsSiteRoot(siteId,personId,db,ct)&&!await CanReadWorkTree(siteId,item.Id,personId,db,ct))return Results.Problem(statusCode:403);var values=await db.Risks.AsNoTracking().AsSplitQuery().Where(x=>x.SiteId==siteId&&x.ObjectType==objectType&&x.ObjectId==objectId).Include(x=>x.Revisions).Include(x=>x.Mitigations).ThenInclude(x=>x.Revisions).OrderByDescending(x=>x.CreatedAt).ToListAsync(ct);return Results.Ok(values.Select(ToResponse));}
 private static async Task<IResult> Create(Guid siteId,string objectType,Guid objectId,RiskRequest request,ClaimsPrincipal user,IAntiforgery anti,HttpContext context,FylkrenDbContext db,CancellationToken ct){if(!await anti.IsRequestValidAsync(context))return Results.BadRequest();if(!PersonId(user,out var personId))return Results.Problem(statusCode:403);var item=await ContextItem(siteId,objectType,objectId,db,ct);if(item is null)return Results.NotFound();if(!await CanManageItem(item,personId,db,ct))return Results.Problem(statusCode:403);if(ValidateRisk(request) is {} error)return error;var owner=await Owner(siteId,request.OwnerPersonId,db,ct);if(owner is null)return Results.ValidationProblem(new Dictionary<string,string[]>{{"ownerPersonId",["Risikoeier må være et aktivt medlem av siten."]}});var now=DateTimeOffset.UtcNow;var risk=new Risk(Guid.NewGuid(),siteId,objectType,objectId,personId,now);db.Risks.Add(risk);db.RiskRevisions.Add(new RiskRevision(Guid.NewGuid(),risk.Id,1,request.Title!,request.Description!,request.Probability,request.Impact,owner.Value.Id,owner.Value.Name,request.Status!,request.DueDate,request.ResidualProbability,request.ResidualImpact,personId,now));Audit(db,siteId,personId,"risk.created",risk.Id,now);await db.SaveChangesAsync(ct);return Results.Created($"/api/risks/{risk.Id}",new{risk.Id});}
 private static async Task<IResult> Revise(Guid riskId,RiskRevisionRequest request,ClaimsPrincipal user,IAntiforgery anti,HttpContext context,FylkrenDbContext db,CancellationToken ct){if(!await anti.IsRequestValidAsync(context))return Results.BadRequest();if(!PersonId(user,out var personId))return Results.Problem(statusCode:403);var risk=await db.Risks.Include(x=>x.Revisions).SingleOrDefaultAsync(x=>x.Id==riskId,ct);if(risk is null)return Results.NotFound();var item=await ContextItem(risk.SiteId,risk.ObjectType,risk.ObjectId,db,ct);if(item is null||!await CanManageItem(item,personId,db,ct))return Results.Problem(statusCode:403);var latest=risk.Revisions.Max(x=>x.Version);if(latest!=request.ExpectedVersion)return Results.Conflict(new{error="Risikoen er endret av en annen bruker. Last inn siste versjon."});if(ValidateRisk(request) is{} error)return error;var owner=await Owner(risk.SiteId,request.OwnerPersonId,db,ct);if(owner is null)return Results.ValidationProblem(new Dictionary<string,string[]>{{"ownerPersonId",["Risikoeier må være et aktivt medlem av siten."]}});var now=DateTimeOffset.UtcNow;db.RiskRevisions.Add(new RiskRevision(Guid.NewGuid(),risk.Id,latest+1,request.Title!,request.Description!,request.Probability,request.Impact,owner.Value.Id,owner.Value.Name,request.Status!,request.DueDate,request.ResidualProbability,request.ResidualImpact,personId,now));Audit(db,risk.SiteId,personId,"risk.revised",risk.Id,now);await db.SaveChangesAsync(ct);return Results.Ok(new{risk.Id,version=latest+1});}
 private static async Task<IResult> AddMitigation(Guid riskId,MitigationRequest request,ClaimsPrincipal user,IAntiforgery anti,HttpContext context,FylkrenDbContext db,CancellationToken ct){if(!await anti.IsRequestValidAsync(context))return Results.BadRequest();if(!PersonId(user,out var personId))return Results.Problem(statusCode:403);var risk=await db.Risks.SingleOrDefaultAsync(x=>x.Id==riskId,ct);if(risk is null)return Results.NotFound();var item=await ContextItem(risk.SiteId,risk.ObjectType,risk.ObjectId,db,ct);if(item is null||!await CanManageItem(item,personId,db,ct))return Results.Problem(statusCode:403);if(ValidateAction(request) is{} error)return error;var owner=await Owner(risk.SiteId,request.OwnerPersonId,db,ct);if(owner is null)return Results.ValidationProblem(new Dictionary<string,string[]>{{"ownerPersonId",["Tiltakseier må være et aktivt medlem av siten."]}});var now=DateTimeOffset.UtcNow;var action=new RiskMitigation(Guid.NewGuid(),risk.Id,personId,now);db.RiskMitigations.Add(action);db.RiskMitigationRevisions.Add(new RiskMitigationRevision(Guid.NewGuid(),action.Id,1,request.Action!,owner.Value.Id,owner.Value.Name,request.Status!,request.DueDate,personId,now));Audit(db,risk.SiteId,personId,"risk.mitigation-created",action.Id,now);await db.SaveChangesAsync(ct);return Results.Created($"/api/risks/mitigations/{action.Id}",new{action.Id});}
 private static async Task<IResult> ReviseMitigation(Guid mitigationId,MitigationRevisionRequest request,ClaimsPrincipal user,IAntiforgery anti,HttpContext context,FylkrenDbContext db,CancellationToken ct){if(!await anti.IsRequestValidAsync(context))return Results.BadRequest();if(!PersonId(user,out var personId))return Results.Problem(statusCode:403);var action=await db.RiskMitigations.Include(x=>x.Revisions).Include(x=>x.Risk).SingleOrDefaultAsync(x=>x.Id==mitigationId,ct);if(action is null)return Results.NotFound();var item=await ContextItem(action.Risk.SiteId,action.Risk.ObjectType,action.Risk.ObjectId,db,ct);if(item is null||!await CanManageItem(item,personId,db,ct))return Results.Problem(statusCode:403);var latest=action.Revisions.Max(x=>x.Version);if(latest!=request.ExpectedVersion)return Results.Conflict(new{error="Tiltaket er endret av en annen bruker. Last inn siste versjon."});if(ValidateAction(request)is{} error)return error;var owner=await Owner(action.Risk.SiteId,request.OwnerPersonId,db,ct);if(owner is null)return Results.ValidationProblem(new Dictionary<string,string[]>{{"ownerPersonId",["Tiltakseier må være et aktivt medlem av siten."]}});var now=DateTimeOffset.UtcNow;db.RiskMitigationRevisions.Add(new RiskMitigationRevision(Guid.NewGuid(),action.Id,latest+1,request.Action!,owner.Value.Id,owner.Value.Name,request.Status!,request.DueDate,personId,now));Audit(db,action.Risk.SiteId,personId,"risk.mitigation-revised",action.Id,now);await db.SaveChangesAsync(ct);return Results.Ok(new{action.Id,version=latest+1});}
 private static IResult? ValidateRisk(RiskRequest r){var e=new Dictionary<string,string[]>();if((r.Title??"").Trim().Length is <2 or >200)e["title"]=["Tittel må være mellom 2 og 200 tegn."];if((r.Description??"").Trim().Length is <2 or >10000)e["description"]=["Beskrivelse må være mellom 2 og 10 000 tegn."];if(r.Probability is<1 or>5||r.Impact is<1 or>5)e["assessment"]=["Sannsynlighet og konsekvens må være mellom 1 og 5."];if(!RiskStatuses.Contains(r.Status??""))e["status"]=["Ugyldig risikostatus."];if((r.ResidualProbability is null)!=(r.ResidualImpact is null)||r.ResidualProbability is<1 or>5||r.ResidualImpact is<1 or>5)e["residualRisk"]=["Oppgi både gjenværende sannsynlighet og konsekvens mellom 1 og 5."];return e.Count==0?null:Results.ValidationProblem(e);}
 private static IResult? ValidateAction(MitigationRequest r){var e=new Dictionary<string,string[]>();if((r.Action??"").Trim().Length is<2 or>4000)e["action"]=["Tiltaket må være mellom 2 og 4000 tegn."];if(!ActionStatuses.Contains(r.Status??""))e["status"]=["Ugyldig tiltaksstatus."];return e.Count==0?null:Results.ValidationProblem(e);}
 private static async Task<(Guid Id,string Name)?> Owner(Guid siteId,Guid id,FylkrenDbContext db,CancellationToken ct){var value=await db.SiteMemberships.AsNoTracking().Where(x=>x.SiteId==siteId&&x.PersonId==id&&x.IsActive&&x.Person.IsActive).Select(x=>new{x.PersonId,x.Person.DisplayName}).SingleOrDefaultAsync(ct);return value is null?null:(value.PersonId,value.DisplayName);}
 private static async Task<WorkItem?> ContextItem(Guid siteId,string type,Guid id,FylkrenDbContext db,CancellationToken ct){if(!ObjectTypes.Contains(type))return null;if(type is "task" or "assignment")return await db.WorkItems.SingleOrDefaultAsync(x=>x.SiteId==siteId&&x.Id==id,ct);if(type=="plan")return await db.WorkflowRuns.Where(x=>x.Id==id&&x.WorkItem.SiteId==siteId).Select(x=>x.WorkItem).SingleOrDefaultAsync(ct);return await db.ExecutionRuns.Where(x=>x.Id==id&&x.WorkItem.SiteId==siteId).Select(x=>x.WorkItem).SingleOrDefaultAsync(ct);}
 private static void Audit(FylkrenDbContext db,Guid siteId,Guid actor,string type,Guid id,DateTimeOffset now)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),siteId,actor,type,"risk",id,now));
 private static object ToResponse(Risk r){var current=r.Revisions.OrderByDescending(x=>x.Version).First();return new{r.Id,r.ObjectType,r.ObjectId,current=new{current.Version,current.Title,current.Description,current.Probability,current.Impact,current.Score,current.Level,current.OwnerPersonId,current.OwnerNameSnapshot,current.Status,current.DueDate,current.ResidualProbability,current.ResidualImpact,current.ResidualScore,current.ResidualLevel,current.RecordedAt},mitigations=r.Mitigations.Select(a=>{var v=a.Revisions.OrderByDescending(x=>x.Version).First();return new{a.Id,v.Version,v.Action,v.OwnerPersonId,v.OwnerNameSnapshot,v.Status,v.DueDate,v.RecordedAt};}),history=r.Revisions.OrderByDescending(x=>x.Version).Skip(1).Select(x=>new{x.Version,x.Title,x.Score,x.Level,x.ResidualScore,x.ResidualLevel,x.RecordedAt})};}
 private record RiskRequest(string? ObjectType,string? Title,string? Description,int Probability,int Impact,Guid OwnerPersonId,string? Status,DateOnly? DueDate,int? ResidualProbability,int? ResidualImpact);private sealed record RiskRevisionRequest(int ExpectedVersion,string? Title,string? Description,int Probability,int Impact,Guid OwnerPersonId,string? Status,DateOnly? DueDate,int? ResidualProbability,int? ResidualImpact):RiskRequest(null,Title,Description,Probability,Impact,OwnerPersonId,Status,DueDate,ResidualProbability,ResidualImpact);private record MitigationRequest(string? Action,Guid OwnerPersonId,string? Status,DateOnly? DueDate);private sealed record MitigationRevisionRequest(int ExpectedVersion,string? Action,Guid OwnerPersonId,string? Status,DateOnly? DueDate):MitigationRequest(Action,OwnerPersonId,Status,DueDate);
}
